mapper.select:
select day_result_id, schedule_id, user_id, user_name, shop_id, business_date, shift_id, scheduled_minutes, worked_minutes, paid_leave_minutes, unpaid_leave_minutes, absence_minutes, late_minutes, early_leave_minutes, result_status, exception_codes, settled_at, row_version from oa_attendance_day_result where day_result_id in
#{dayResultId}
order by day_result_id for update

select coalesce(sum(case
         when adjustment_action = 'APPLY' then adjustment_minutes
         when adjustment_action = 'REVERSE' then -adjustment_minutes
         else 0 end), 0)
from oa_attendance_time_credit_adjustment
where source_day_result_id = #{sourceDayResultId}

select coalesce(sum(case
         when adjustment_action = 'APPLY' then adjustment_minutes
         when adjustment_action = 'REVERSE' then -adjustment_minutes
         else 0 end), 0)
from oa_attendance_time_credit_adjustment
where target_day_result_id = #{targetDayResultId}

select 
from oa_attendance_time_credit_adjustment
where shop_id = #{shopId}
  and operator_user_id = #{operatorUserId}
  and client_request_id = #{clientRequestId}

select count(1)
from oa_salary_record
where user_id = #{userId}
  and salary_month = #{salaryMonth}
